def remove_duplicates_preserve_order(lst):
    seen = []
    result = []
    for x in lst:
        if x not in seen:
            seen.append(x)
            result.append(x)
    return result

def rotate_list_left(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[n:] + lst[:n]

def rotate_list_right(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[-n:] + lst[:-n] if n != 0 else lst[:]

def flatten_one_level(lst):
    result = []
    for x in lst:
        if isinstance(x, list):
            result.extend(x)
        else:
            result.append(x)
    return result

def find_duplicates(lst):
    seen = set()
    added = set()
    result = []
    for x in lst:
        if x in seen and x not in added:
            result.append(x)
            added.add(x)
        seen.add(x)
    return result

def group_consecutive(lst):
    if not lst:
        return []
    result = []
    prev = lst[0]
    count = 1
    for x in lst[1:]:
        if x == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = x
            count = 1
    result.append([prev, count])
    return result

def second_largest(lst):
    distinct = sorted(set(lst), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]

def intersection_preserve_order(a, b):
    bset = set(b)
    result = []
    seen = set()
    for x in a:
        if x in bset and x not in seen:
            result.append(x)
            seen.add(x)
    return result

def difference_preserve_order(a, b):
    bset = set(b)
    result = []
    seen = set()
    for x in a:
        if x not in bset and x not in seen:
            result.append(x)
            seen.add(x)
    return result

def partition_odd_even(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def dedupe_adjacent(lst):
    if not lst:
        return []
    result = [lst[0]]
    for x in lst[1:]:
        if x != result[-1]:
            result.append(x)
    return result

def count_occurrences(lst):
    d = {}
    for x in lst:
        d[x] = d.get(x, 0) + 1
    return d

def most_frequent_element(lst):
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    best = lst[0]
    best_count = counts[lst[0]]
    for x in lst:
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

def interleave_lists(a, b):
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result
